import re

LEGAL = re.compile(r"^[A-Za-z0-9_.\-]{1,128}$")


def qualify(tools_by_server, separator="."):
    """Return the tool names a model is shown, in server order, then tool order.

    `tools_by_server` maps a configuration key to the list of tool names that
    server publishes. A name published by more than one server is qualified as
    key + separator + name on every server that publishes it; any other name
    stays bare. A published name that LEGAL does not match raises ValueError.
    """
    counts = {}
    for names in tools_by_server.values():
        for name in names:
            counts[name] = counts.get(name, 0) + 1
    published = []
    for server, names in tools_by_server.items():
        for name in names:
            shown = f"{server}{separator}{name}" if counts[name] > 1 else name
            if not LEGAL.match(shown):
                raise ValueError(f"illegal tool name {shown!r} from server {server!r}")
            published.append(shown)
    return published

questions.tests:
assert qualify({"docs": ["search"], "files": ["search", "read"]}) == ["docs.search", "files.search", "read"], "qualify both sides, and only the contested name"
assert qualify({"system-info": ["get_system_info"], "docs": ["search"]}) == ["get_system_info", "search"], "a unique name stays bare"
assert qualify({"a": ["search", "read", "list"], "b": ["search", "write"], "c": ["read", "ping"]}) == ["a.search", "a.read", "list", "b.search", "write", "c.read", "ping"]
assert qualify({"docs": ["search"], "files": ["search"]}, separator="_") == ["docs_search", "files_search"]
for bad in ({"bad": ["group/search"]}, {"my docs": ["search"], "files": ["search"]}):
    try:
        qualify(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(f"{bad} must raise ValueError")
assert qualify({"x": ["a" * 128]}) == ["a" * 128], "128 characters is still legal"
try:
    qualify({"long": ["a" * 125], "other": ["a" * 125]})
except ValueError:
    pass
else:
    raise AssertionError("a qualified name longer than 128 characters must raise")
assert qualify({}) == []
print("all qualify tests passed")

