def decide(server, tool, annotations, policy):
    """Return "allow", "deny" or "ask" for one call, before any remembered decision.

    `annotations` is a dict of hints such as {"readOnlyHint": True}, or None.
    `policy` has "auto_approve_read_only" (a bool), "allowlist" and "denylist"
    (sets of "server.tool" keys or bare tool names).
    """
    ann = annotations or {}
    key = f"{server}.{tool}"
    if key in policy.get("denylist", ()) or tool in policy.get("denylist", ()):
        return "deny"
    if key in policy.get("allowlist", ()) or tool in policy.get("allowlist", ()):
        return "allow"
    if ann.get("destructiveHint"):
        return "ask"
    if ann.get("readOnlyHint") and policy.get("auto_approve_read_only", True):
        return "allow"
    return "ask"
